create or replace function public.create_field_visit(p_assigned_staff_id uuid,p_customer_name text,p_customer_phone text default null,p_customer_address text default null,p_lat numeric default null,p_lng numeric default null,p_radius_meters numeric default 150,p_scheduled_at timestamptz default null,p_notes text default null) returns public.field_visits language plpgsql security definer set search_path='' as $$ declare v_staff public.staff%rowtype; v_assignee public.staff%rowtype; v_visit public.field_visits%rowtype; begin select * into v_staff from public.staff where user_id=(select auth.uid()) limit 1; if v_staff.id is null or v_staff.role not in('owner','admin','manager','team_lead') then raise exception using errcode='42501',message='NOT_AUTHORIZED'; end if; select * into v_assignee from public.staff where id=p_assigned_staff_id and business_id=v_staff.business_id limit 1; if v_assignee.id is null then raise exception using errcode='P0001',message='INVALID_ASSIGNEE'; end if; insert into public.field_visits(business_id,assigned_staff_id,customer_name,customer_phone,customer_address,latitude,longitude,radius_meters,scheduled_at,notes,created_by) values(v_staff.business_id,p_assigned_staff_id,p_customer_name,p_customer_phone,p_customer_address,p_lat,p_lng,p_radius_meters,p_scheduled_at,p_notes,v_staff.id) returning * into v_visit; return v_visit; end; $$;

create or replace function public.start_field_visit(p_visit_id uuid,p_lat numeric default null,p_lng numeric default null,p_accuracy_meters numeric default null,p_device text default null,p_network_state text default 'online',p_client_event_id uuid default gen_random_uuid()) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_staff public.staff%rowtype; v_visit public.field_visits%rowtype; v_now timestamptz:=now(); v_distance numeric; v_verification text:='unverified'; v_reason text:='Customer location not configured'; v_event_id uuid; begin select * into v_staff from public.staff where user_id=(select auth.uid()) limit 1; select * into v_visit from public.field_visits where id=p_visit_id and business_id=v_staff.business_id for update; if v_visit.id is null or v_visit.assigned_staff_id<>v_staff.id then raise exception using errcode='42501',message='VISIT_NOT_ASSIGNED'; end if; if v_visit.status in('completed','cancelled') then raise exception using errcode='P0001',message='VISIT_CLOSED'; end if; if p_lat is not null and p_lng is not null and v_visit.customer_location is not null then v_distance:=extensions.st_distance(v_visit.customer_location,extensions.st_setsrid(extensions.st_makepoint(p_lng::double precision,p_lat::double precision),4326)::extensions.geography); if v_distance<=v_visit.radius_meters then v_verification:='verified';v_reason:='Within customer location radius'; else v_verification:='outside_geofence';v_reason:='Outside customer location radius'; end if; end if; update public.field_visits set status=case when v_verification='verified' then 'verified' else 'arrived' end,arrived_at=v_now,arrival_lat=p_lat,arrival_lng=p_lng,arrival_accuracy_meters=p_accuracy_meters,arrival_distance_meters=v_distance,arrival_verification_status=v_verification,arrival_verification_reason=v_reason,updated_at=v_now where id=v_visit.id returning * into v_visit; insert into public.field_visit_events(business_id,visit_id,staff_id,event_type,client_event_id,captured_at,server_received_at,latitude,longitude,accuracy_meters,distance_meters,verification_status,verification_reason,device,network_state) values(v_staff.business_id,v_visit.id,v_staff.id,case when v_verification='verified' then 'verified' else 'arrived' end,p_client_event_id,v_now,v_now,p_lat,p_lng,p_accuracy_meters,v_distance,v_verification,v_reason,p_device,p_network_state) on conflict(client_event_id) do nothing returning id into v_event_id; return jsonb_build_object('ok',true,'visit_id',v_visit.id,'event_id',coalesce(v_event_id,p_client_event_id),'status',v_visit.status,'verification_status',v_verification,'distance_meters',v_distance); end; $$;

create or replace function public.complete_field_visit(p_visit_id uuid,p_outcome text,p_notes text default null,p_lat numeric default null,p_lng numeric default null,p_accuracy_meters numeric default null,p_device text default null,p_network_state text default 'online',p_client_event_id uuid default gen_random_uuid()) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_staff public.staff%rowtype; v_visit public.field_visits%rowtype; v_now timestamptz:=now(); v_distance numeric; v_verification text:='unverified'; v_reason text:='Customer location not configured'; v_event_id uuid; begin select * into v_staff from public.staff where user_id=(select auth.uid()) limit 1; select * into v_visit from public.field_visits where id=p_visit_id and business_id=v_staff.business_id for update; if v_visit.id is null or v_visit.assigned_staff_id<>v_staff.id then raise exception using errcode='42501',message='VISIT_NOT_ASSIGNED'; end if; if v_visit.status in('completed','cancelled') then raise exception using errcode='P0001',message='VISIT_CLOSED'; end if; if p_lat is not null and p_lng is not null and v_visit.customer_location is not null then v_distance:=extensions.st_distance(v_visit.customer_location,extensions.st_setsrid(extensions.st_makepoint(p_lng::double precision,p_lat::double precision),4326)::extensions.geography); if v_distance<=v_visit.radius_meters then v_verification:='verified';v_reason:='Within customer location radius'; else v_verification:='outside_geofence';v_reason:='Outside customer location radius'; end if; end if; update public.field_visits set status='completed',completed_at=v_now,completion_lat=p_lat,completion_lng=p_lng,completion_accuracy_meters=p_accuracy_meters,completion_distance_meters=v_distance,completion_verification_status=v_verification,completion_verification_reason=v_reason,outcome=p_outcome,notes=coalesce(p_notes,notes),updated_at=v_now where id=v_visit.id returning * into v_visit; insert into public.field_visit_events(business_id,visit_id,staff_id,event_type,client_event_id,captured_at,server_received_at,latitude,longitude,accuracy_meters,distance_meters,verification_status,verification_reason,device,network_state,payload) values(v_staff.business_id,v_visit.id,v_staff.id,'completed',p_client_event_id,v_now,v_now,p_lat,p_lng,p_accuracy_meters,v_distance,v_verification,v_reason,p_device,p_network_state,jsonb_build_object('outcome',p_outcome)) on conflict(client_event_id) do nothing returning id into v_event_id; return jsonb_build_object('ok',true,'visit_id',v_visit.id,'event_id',coalesce(v_event_id,p_client_event_id),'status','completed','verification_status',v_verification,'distance_meters',v_distance); end; $$;

revoke all on function public.create_field_visit(uuid,text,text,text,numeric,numeric,numeric,timestamptz,text) from public,anon;
revoke all on function public.start_field_visit(uuid,numeric,numeric,numeric,text,text,uuid) from public,anon;
revoke all on function public.complete_field_visit(uuid,text,text,numeric,numeric,numeric,text,text,uuid) from public,anon;
grant execute on function public.create_field_visit(uuid,text,text,text,numeric,numeric,numeric,timestamptz,text) to authenticated;
grant execute on function public.start_field_visit(uuid,numeric,numeric,numeric,text,text,uuid) to authenticated;
grant execute on function public.complete_field_visit(uuid,text,text,numeric,numeric,numeric,text,text,uuid) to authenticated;

notify pgrst,'reload schema';